:root {
  --ink: #202228;
  --paper: #fffdf7;
  --line: #ded9cb;
  --muted: #72736e;
  --lime: #d7ef50;
  --deep-lime: #2b3b12;
  --soft: #f2f0e9;
}

* {
  box-sizing: border-box;
}

.appointment-card {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--ink);
}

.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  letter-spacing: 0.12em;
}

.brand-mark {
  display: grid;
  width: 23px;
  height: 23px;
  place-items: center;
  border-radius: 50%;
  background: var(--ink);
  color: var(--lime);
  font-size: 14px;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--lime);
  color: var(--deep-lime);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.service-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 16px;
}

.barber-avatar {
  display: grid;
  width: 48px;
  height: 48px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 14px;
  background: var(--ink);
  color: var(--paper);
  font-size: 13px;
  font-weight: 800;
}

.service-copy h1,
.service-copy p {
  margin: 0;
}

.eyebrow,
.detail-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.service-copy h1 {
  margin: 3px 0 2px;
  font-size: 19px;
  line-height: 1.15;
}

.duration {
  color: var(--muted);
  font-size: 13px;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.detail {
  min-width: 0;
  padding: 11px 16px;
}

.detail + .detail {
  border-left: 1px solid var(--line);
}

.detail-label {
  margin: 0 0 4px;
}

.detail-value {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 16px;
  background: var(--soft);
}

.note {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.actions {
  display: flex;
  gap: 7px;
}

button {
  border: 1px solid var(--ink);
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 700;
}

.secondary {
  background: var(--paper);
  color: var(--ink);
}

.primary {
  background: var(--ink);
  color: var(--paper);
}
